package com.example.watchdiary.util

import com.example.watchdiary.data.model.ContentType
import com.example.watchdiary.data.model.DiaryEntry
import com.google.gson.JsonParser
import java.time.LocalDate

object ImportParser {
    data class TextImportResult(val entries: List<DiaryEntry>, val invalidLines: Int)

    /** Reads the same JSON array produced by ExportManager. IDs are regenerated by Room. */
    fun parseJson(text: String): List<DiaryEntry> {
        val root = JsonParser.parseString(text)
        require(root.isJsonArray) { "Ожидался JSON-массив записей" }
        return root.asJsonArray.mapIndexed { index, element ->
            try {
                require(element.isJsonObject)
                val item = element.asJsonObject
                val title = item.get("title").asString.trim()
                require(title.isNotEmpty())
                val type = parseType(item.get("contentType").asString)
                    ?: error("Unknown content type")
                val date = LocalDate.parse(item.get("watchDate").asString)
                val rating = item.get("rating").asInt
                require(rating in 0..5)
                val comment = item.get("comment")?.takeUnless { it.isJsonNull }?.asString.orEmpty()
                DiaryEntry(
                    title = title,
                    contentType = type,
                    watchDate = date,
                    rating = rating,
                    comment = comment
                )
            } catch (e: Exception) {
                throw IllegalArgumentException("Некорректная запись №${index + 1}", e)
            }
        }
    }

    fun parse(text: String): List<DiaryEntry> {
        return parseWithReport(text).entries
    }

    /** Keep valid rows, but report invalid rows instead of silently losing them. */
    fun parseWithReport(text: String): TextImportResult {
        val lines = text
            .lines()
            .map { it.trim() }
            .filter { it.isNotBlank() }
        val entries = lines.mapNotNull { parseLine(it) }
        return TextImportResult(entries, lines.size - entries.size)
    }

    private fun parseLine(line: String): DiaryEntry? {
        // Limit keeps additional '|' characters inside the comment.
        val parts = line.split("|", limit = 5).map { it.trim() }
        if (parts.size < 5) return null

        val title = parts[0]
        if (title.isBlank()) return null
        val type = parseType(parts[1]) ?: return null
        val date = runCatching { LocalDate.parse(parts[2]) }.getOrNull() ?: return null
        val rating = parts[3].toIntOrNull()?.takeIf { it in 0..5 } ?: return null
        val comment = parts[4]

        return DiaryEntry(
            title = title,
            contentType = type,
            watchDate = date,
            rating = rating,
            comment = comment
        )
    }

    private fun parseType(value: String): ContentType? {
        return when (value.uppercase()) {
            "MOVIE" -> ContentType.MOVIE
            "SERIES" -> ContentType.SERIES
            "ANIME" -> ContentType.ANIME
            else -> null
        }
    }
}
